config.files:
{
    "baseq3/server_octail.cfg": {
        "parser": "file",
        "find": {
            "set sv_hostname ": "set sv_hostname \"{{server.environment.SERVER_NAME}}\"",
            "set sv_maxClients ": "set sv_maxClients {{server.environment.MAX_PLAYERS}}",
            "set g_password ": "set g_password \"{{server.environment.SERVER_PASSWORD}}\"",
            "set sv_tags ": "set sv_tags \"{{server.environment.TAGS}}\"",
            "set serverstartup ": "set serverstartup \"map {{server.environment.MAP}} {{server.environment.FACTORY}}\"",
            "set zmq_rcon_enable ": "set zmq_rcon_enable {{server.environment.RCON_ENABLED}}",
            "set zmq_rcon_port ": "set zmq_rcon_port {{server.environment.RCON_PORT}}",
            "set zmq_rcon_password ": "set zmq_rcon_password \"{{server.environment.RCON_PASSWORD}}\""
        }
    }
}

config.startup:
{
    "done": [
        "zmq stats and rcon passwords updated",
        "------- Game Initialization -------"
    ]
}
